\copy (with lines as ( select s.id, t.ord, t.l from site.bp_shared_logs s, lateral regexp_split_to_table(s.scrubbed, E'\n') with ordinality as t(l, ord) ) select id || ' ' || ord || ' ' || replace(encode(convert_to(l,'UTF8'),'base64'), E'\n','') from lines where position('planet cells:' in l) > 0 or position('[QuantumTravel]' in l) > 0 or position('requested inventory for Location[' in l) > 0 or position('at location [' in l) > 0 or position(':Location:' in l) > 0 or position('Platform state changed to' in l) > 0 or position('CEntityComponentCommodityUIProvider::' in l) > 0 or position('CEntityComponentShop' in l) > 0 or position('shopName[' in l) > 0 order by id, ord) to stdout
